"""Mechanism prompts generated by exact sport/market; no invented script outcomes.

Until contextual possession/role/lineup data support a causal direction, every
scenario remains UNKNOWN. This is automation of evidence *requests*, not of proof.
"""
from __future__ import annotations
from bta_v07.scenarios import SCRIPT_FAMILIES


def mechanisms(league:str,market:str,side:str,player:str='') -> dict:
    if league=='NFL' and player:family='NFL_PROP'
    elif league=='NBA' and player:family='NBA_PROP'
    elif league=='College football' and market=='h2h':family='CFB_MONEYLINE'
    else:return {'status':'UNSUPPORTED','scenarios':[]}
    over=side.upper() in ('OVER','YES')
    flow={
        'favorite_blowout':'Leading team may reduce pass attempts or rest starters; determine which team owns the selected player',
        'underdog_blowout':'Trailing team may pass more and run less; determine selected player team and role',
        'close_game':'Late-game starters and targets may be preserved; check expected usage',
        'low_scoring':'Lower possessions and efficiency may reduce volume; check exact threshold and variance',
        'shootout':'Higher tempo may increase offensive volume; distribution among teammates remains uncertain',
        'own_team_blowout':'Player may lose late minutes despite efficient early scoring',
        'opponent_blowout':'Player may lose minutes if team trails heavily',
        'slow_game':'Fewer possessions can alter points/rebounds/assists opportunity',
        'fast_game':'More possessions may improve opportunity but also substitution patterns',
        'normal':'Verify opponent-adjusted sustainable quality against current opponent',
        'underdog_early_lead':'Test favorite comeback passing efficiency after a 10- or 14-point deficit',
        'favorite_minus_two_turnovers':'Test defensive resilience under a -2 turnover differential',
        'primary_strength_neutralized':'Identify favorite’s biggest advantage and credible alternative paths to victory',
        'one_possession_fourth_quarter':'Test late quarterback, special-teams and coaching dependability',
    }
    output=[]
    for name in SCRIPT_FAMILIES[family]:
        output.append({'scenario':name,'verdict':'UNKNOWN','mechanism_to_verify':flow[name],
                       'evidence_status':'NOT VERIFIED','evidence_source':None})
    return {'status':'EVIDENCE REQUESTS ONLY','family':family,'scenarios':output,
            'reason':'These are causal hypotheses, not observed counterfactual outcomes.'}


def reverse_failure(forecast:dict)->dict:
    if forecast.get('status') not in ('EXPERIMENTAL_UNCALIBRATED','INSUFFICIENT') or 'sample_games' not in forecast:
        return {'status':'UNKNOWN','reason':'No exact-threshold pregame historical sample'}
    line=forecast['line'];side=forecast['side']
    missed=([row for row in forecast['sample_games'] if row['value']<line]
            if side=='OVER' else [row for row in forecast['sample_games'] if row['value']>line])
    missed=sorted(missed,key=lambda x:x['value'],reverse=side=='UNDER')
    return {'status':'OBSERVED MISSES, CAUSE NOT VERIFIED', 'normal_failure_mechanism':'An ordinary low-opportunity or inefficient game can defeat a favorable average',
            'observed_misses':[{'game':x['game_date'],'value':x['value'],
                                'deficit':round((line-x['value'] if side=='OVER' else x['value']-line),2)}
                               for x in missed[:5]],
            'note':'Do not classify an observed miss as injury/contextual/structural without verified evidence.'}
